insert into public.cities (id, name, lat, lng, known_for, tip_title, tip_text, best_season, seasons, nightlife_tip, sort_order) values
  ('marrakech', 'Marrakech', 31.6295, -7.9811, 'The Red City: souks, palaces and Jemaa el-Fna', 'Lost in the souks?', 'Ask for “Jemaa el-Fna” (jem-AH el-FNA). Almost every main lane leads back to the square, and taxis wait on the Koutoubia side.', 'Spring and autumn; winter is good for sightseeing', array['winter', 'spring', 'autumn']::text[], null, 10),
  ('tangier', 'Tangier', 35.7595, -5.834, 'The gateway between Africa and Europe', 'Downhill or uphill', 'From the Grand Socco, walk downhill into the medina. Uphill leads to the kasbah and its views over the Strait.', 'Spring, summer and early autumn', array['spring', 'summer', 'autumn']::text[], 'Evenings centre on the marina and the city-centre boulevards.', 20),
  ('casablanca', 'Casablanca', 33.5731, -7.5898, 'Morocco’s big modern city and the Hassan II Mosque', 'A big city', 'Casablanca is spread out. Use the tram and red petit taxis; the Hassan II Mosque is easiest by taxi.', 'Spring and autumn; good for city breaks all year', array['spring', 'autumn']::text[], null, 30),
  ('agadir', 'Agadir', 30.4278, -9.5981, 'Beaches and sunshine on the south coast', 'A beach city', 'Agadir was rebuilt after the 1960 earthquake, so there is no old medina. Life centres on the beach and Souk El Had.', 'All year: winter sunshine and summer beaches', array['winter', 'spring', 'summer', 'autumn']::text[], null, 40),
  ('fes', 'Fes', 34.0331, -5.0003, 'The oldest medina, tanneries and craftsmen', 'Lost in Fes el-Bali?', 'The two main streets, Talaa Kebira and Talaa Sghira, both climb up to Bab Boujloud. If you''re walking uphill, you''re usually heading out.', 'Spring and autumn', array['spring', 'autumn']::text[], 'Fes is quiet at night: hotel lounges and live-music venues, mostly in the new town (Ville Nouvelle).', 50),
  ('rabat', 'Rabat', 34.0209, -6.8416, 'The calm capital by the Atlantic', 'Easy to get around', 'Rabat is relaxed and easy to walk. The tram links the city centre, Hassan Tower and Salé across the river.', 'Spring and autumn', array['spring', 'autumn']::text[], null, 60),
  ('essaouira', 'Essaouira', 31.5085, -9.7595, 'A windy, laid-back port on the Atlantic', 'Bring a jacket', 'The medina is a small grid, easy to explore on foot. The wind blows strongly most of the year.', 'Spring to autumn; expect wind', array['spring', 'summer', 'autumn']::text[], 'Listen for Gnawa music in cafés, especially during the Gnaoua World Music Festival in early summer.', 70),
  ('chefchaouen', 'Chefchaouen', 35.1688, -5.2636, 'The blue town in the Rif mountains', 'Small and easy', 'Everything slopes down to Plaza Uta el-Hammam. Head downhill to find the square, uphill to reach Ras el-Maa.', 'Spring and early autumn', array['spring', 'autumn']::text[], 'Evenings are calm: rooftop and medina cafés, sometimes with live music.', 80),
  ('ouarzazate', 'Ouarzazate', 30.9189, -6.8934, 'The door to the desert and Morocco’s film studios', 'Gateway to the south', 'Ouarzazate is the starting point for the Draa and Dades valleys and the desert. Grand taxis and tours leave from here.', 'Spring and autumn; winter days are often pleasant', array['winter', 'spring', 'autumn']::text[], 'Evenings are quiet: hotel lounges, dinner, and starry skies on desert-camp nights.', 90),
  ('ifrane', 'Ifrane', 33.5228, -5.1106, 'The “Switzerland of Morocco” in the Middle Atlas', 'Pack a jacket', 'Ifrane is high in the mountains and much cooler than the rest of Morocco. It can snow in winter.', 'Winter for snow; spring and summer for green landscapes', array['winter', 'spring', 'summer']::text[], 'Evenings are quiet: hotel lounges and cafés.', 100),
  ('meknes', 'Meknes', 33.8935, -5.5473, 'The imperial city of Sultan Moulay Ismail', 'Start at the square', 'Begin at Place el-Hedim. The souks are behind it, and the imperial city lies through Bab Mansour.', 'Spring and autumn', array['spring', 'autumn']::text[], null, 110),
  ('merzouga', 'Merzouga', 31.0802, -4.0133, 'The Sahara dunes of Erg Chebbi', 'Plan your desert night', 'Book your desert camp before you arrive, and ask exactly what is included: transfer, dinner and camel ride.', 'Autumn to spring; summer days are very hot', array['winter', 'autumn']::text[], null, 120)
insert into public.places (city_id, name, kind, description, sort_order) values
  ('marrakech', 'Jemaa el-Fna', 'square', 'The main square and your reference point. Food stalls open around sunset.', 10),
  ('marrakech', 'Koutoubia Mosque', 'sight', 'Its minaret is visible from most of the medina, so use it to get your bearings. Non-Muslims can''t go inside.', 20),
  ('marrakech', 'Bahia Palace', 'sight', 'A 19th-century palace with gardens and painted ceilings, on the south side near the Mellah.', 30),
  ('marrakech', 'El Badi Palace', 'sight', 'The vast ruins of a 16th-century palace, with storks nesting on its walls and views from the terraces.', 40),
  ('marrakech', 'Saadian Tombs', 'sight', 'Richly decorated 16th-century tombs of the Saadian dynasty, beside the Kasbah Mosque.', 50),
  ('marrakech', 'Ben Youssef Madrasa', 'sight', 'A former Quranic school with famous carved cedar and zellige tilework, north of the souks.', 60),
  ('marrakech', 'Bab Agnaou', 'gate', 'Carved stone gate by the Kasbah and the Saadian Tombs.', 70),
  ('marrakech', 'Bab Doukkala', 'gate', 'North-west gate, close to the train and bus stations. Good for catching a taxi.', 80),
  ('marrakech', 'Jardin Majorelle', 'garden', 'The cobalt-blue garden restored by Yves Saint Laurent, with cacti, bamboo and a Berber museum. Book tickets ahead in busy months.', 90),
  ('marrakech', 'Le Jardin Secret', 'garden', 'A restored riad garden in the medina. A calm break from the souks.', 100),
  ('marrakech', 'Menara Gardens', 'garden', 'Olive groves around a large pool and pavilion, with the Atlas mountains behind on clear days.', 110),
  ('marrakech', 'Anima Garden', 'garden', 'An art garden created by André Heller, about 30 minutes south of the city.', 120),
  ('marrakech', 'Cyber Park', 'garden', 'A free public park with shady paths and orange trees, close to the Koutoubia.', 130),
  ('marrakech', 'Ourika Valley', 'nature', 'An Atlas valley about an hour away, with riverside cafés and waterfalls at Setti Fatma.', 140),
  ('marrakech', 'Agafay Desert', 'nature', 'A stony desert about 40 minutes away, for sunsets, camel rides and desert camps.', 150),
  ('marrakech', 'Ouzoud Waterfalls', 'nature', 'Spectacular waterfalls about three hours away, often with Barbary macaques nearby. A full day trip.', 160),
  ('marrakech', 'Comptoir Darna', 'nightlife', 'Dinner with live music and dance shows, in the Hivernage district.', 170),
  ('marrakech', 'Theatro Marrakech', 'nightlife', 'A nightclub in a former theatre, in Hivernage.', 180),
  ('marrakech', '555 Famous Club', 'nightlife', 'A large nightclub in Hivernage.', 190),
  ('tangier', 'Grand Socco', 'square', 'The busy square between the new town and the medina. Start here.', 10),
  ('tangier', 'Petit Socco', 'square', 'A small café square in the heart of the medina.', 20),
  ('tangier', 'Kasbah Museum', 'sight', 'The former sultan''s palace at the top of the kasbah, with views across the Strait of Gibraltar.', 30),
  ('tangier', 'American Legation Museum', 'sight', 'The first property the United States owned abroad, now a museum of art and history in the medina.', 40),
  ('tangier', 'Bab el-Kasbah', 'gate', 'The gate into the kasbah from the upper medina.', 50),
  ('tangier', 'Perdicaris Park', 'garden', 'Forest walks with sea views west of the city, around a historic villa.', 60),
  ('tangier', 'Villa Harris Park', 'garden', 'The restored gardens of a 19th-century villa on the bay, east of the city.', 70),
  ('tangier', 'Cap Spartel', 'nature', 'The lighthouse where the Atlantic meets the Mediterranean.', 80),
  ('tangier', 'Caves of Hercules', 'nature', 'Sea caves near Cap Spartel. Go by taxi.', 90),
  ('tangier', 'Achakar Beach', 'nature', 'A long Atlantic beach south of Cap Spartel.', 100),
  ('tangier', 'Dalia Beach', 'nature', 'A sheltered Mediterranean cove east of Tangier.', 110),
  ('casablanca', 'Hassan II Mosque', 'sight', 'One of the largest mosques in the world, built partly over the ocean. Non-Muslims can visit on guided tours.', 10),
  ('casablanca', 'Quartier Habous', 'market', 'The "new medina" built in the 1930s, with arcades, olive sellers and pastry shops.', 20),
  ('casablanca', 'Old Medina', 'market', 'A small, everyday medina next to the port, good for a short walk.', 30),
  ('casablanca', 'Place Mohammed V', 'square', 'The grand square of the city centre, surrounded by 1920s Mauresque buildings.', 40),
  ('casablanca', 'Morocco Mall', 'market', 'A huge seaside shopping mall with an aquarium.', 50),
  ('casablanca', 'Arab League Park', 'garden', 'The city’s largest central park, with palm-lined walks and cafés.', 60),
  ('casablanca', 'Bouskoura Forest', 'garden', 'Eucalyptus and pine forest south of the city, for walks, runs and picnics.', 70),
  ('casablanca', 'Corniche Ain Diab', 'nature', 'The ocean-front promenade with beaches, cafés and sunsets.', 80),
  ('casablanca', 'Sky 28', 'nightlife', 'A bar on the 28th floor of the Kenzi Tower, with views over the city.', 90),
  ('casablanca', 'Le Cabestan', 'nightlife', 'A restaurant and lounge on the ocean cliffs by the El Hank lighthouse.', 100),
  ('agadir', 'Agadir Oufella', 'sight', 'The hilltop kasbah ruins with the best view over the bay, reachable by cable car.', 10),
  ('agadir', 'Amazigh Heritage Museum', 'sight', 'Jewellery, carpets and crafts of Amazigh (Berber) culture.', 20),
  ('agadir', 'Souk El Had', 'market', 'One of the biggest markets in Morocco, with thousands of stalls selling food, spices and crafts.', 30),
  ('agadir', 'Agadir Marina', 'sight', 'The modern marina at the north end of the beach.', 40),
  ('agadir', 'Jardin de Olhão', 'garden', 'A garden named after Agadir’s Portuguese twin town, with a small museum about the city before 1960.', 50),
  ('agadir', 'Crocoparc', 'garden', 'Botanical gardens with Nile crocodiles, east of the city.', 60),
  ('agadir', 'Agadir Beach', 'nature', 'A long sandy beach with a seafront promenade, cafés and restaurants.', 70),
  ('agadir', 'Taghazout', 'nature', 'A laid-back surf village about 20 km north.', 80),
  ('agadir', 'Paradise Valley', 'nature', 'Palm-lined gorges and natural pools in the foothills north-east of Agadir.', 90),
  ('agadir', 'Imouzzer', 'nature', 'A mountain village known for its waterfalls, best after rain.', 100),
  ('agadir', 'Papagayo', 'nightlife', 'A beach club on the seafront.', 110),
  ('fes', 'Bab Boujloud (Blue Gate)', 'gate', 'The main entrance to the old city. Taxis and cafés right outside.', 10),
  ('fes', 'Chouara Tannery', 'sight', 'The famous leather dye pits. Watch from the leather shop terraces; a mint sprig helps with the smell.', 20),
  ('fes', 'Al-Qarawiyyin', 'sight', 'One of the oldest universities in the world. Non-Muslims can look through the doors.', 30),
  ('fes', 'Bou Inania Madrasa', 'sight', 'A stunning 14th-century madrasa near Bab Boujloud, open to visitors.', 40),
  ('fes', 'Place Seffarine', 'square', 'The coppersmiths'' square. Follow the sound of hammering.', 50),
  ('fes', 'Bab R''cif', 'gate', 'Lower gate, deep in the medina. Handy for taxis when you''re far from Bab Boujloud.', 60),
  ('fes', 'Jnan Sbil Gardens', 'garden', 'Restored royal gardens between Fes el-Bali and Fes el-Jdid, with fountains and a lake.', 70),
  ('rabat', 'Kasbah of the Udayas', 'sight', 'A 12th-century fortress above the river mouth, with blue-and-white lanes and the Andalusian Gardens.', 10),
  ('rabat', 'Hassan Tower', 'sight', 'The unfinished 12th-century minaret beside the Mausoleum of Mohammed V, where royal guards stand at the gates.', 20),
  ('rabat', 'Chellah', 'sight', 'Roman and Merinid ruins in a walled garden, home to nesting storks.', 30),
  ('rabat', 'Rue des Consuls', 'market', 'The medina''s calmest souk street, known for carpets and crafts, with little hassle.', 40),
  ('rabat', 'Bab el-Had', 'gate', 'The medina''s main western gate, close to petit taxis.', 50),
  ('rabat', 'Jardin d''Essais Botaniques', 'garden', 'Historic botanical gardens with shaded paths and rare plants.', 60),
  ('rabat', 'Ibn Sina Park', 'garden', 'Also called Hilton Forest: a large wooded park for walks and running.', 70),
  ('rabat', 'Bouregreg Marina', 'nature', 'Cafés and boats on the river between Rabat and Salé.', 80),
  ('rabat', 'Rabat Beach', 'nature', 'The city beach below the Kasbah of the Udayas, popular with surfers.', 90),
  ('rabat', 'Le Dhow', 'nightlife', 'A restaurant and bar on a wooden boat moored on the Bouregreg river.', 100),
  ('essaouira', 'Skala de la Ville', 'sight', 'The sea ramparts with old cannons and views over the Atlantic.', 10),
  ('essaouira', 'Fishing port', 'sight', 'Blue boats and fresh fish grilled on the spot. Agree the price before they cook.', 20),
  ('essaouira', 'Place Moulay Hassan', 'square', 'The main square between the medina and the port.', 30),
  ('essaouira', 'Bab Doukkala', 'gate', 'The northern gate of the medina, near the bus station.', 40),
  ('essaouira', 'Essaouira Beach', 'nature', 'A long windy beach, popular for kitesurfing and windsurfing.', 50),
  ('essaouira', 'Diabat', 'nature', 'Dunes and a quiet village just south of the beach, reachable on foot or on horseback.', 60),
  ('essaouira', 'Sidi Kaouki', 'nature', 'A wild surf beach about 25 km south.', 70),
  ('essaouira', 'Argan forests', 'nature', 'Argan trees and women’s cooperatives making argan oil along the roads out of town.', 80),
  ('essaouira', 'Taros', 'nightlife', 'A rooftop bar and restaurant above Place Moulay Hassan, with live music.', 90),
  ('chefchaouen', 'Plaza Uta el-Hammam', 'square', 'The main square with cafés facing the kasbah.', 10),
  ('chefchaouen', 'The Kasbah', 'sight', 'A red-walled fortress with a garden and small museum.', 20),
  ('chefchaouen', 'Bab el-Ain', 'gate', 'The main gate, where taxis and the road into town meet.', 30),
  ('chefchaouen', 'Ras el-Maa', 'nature', 'The spring at the top of town where locals wash clothes.', 40),
  ('chefchaouen', 'Spanish Mosque viewpoint', 'nature', 'A 30-minute walk up for the best sunset view over the blue city.', 50),
  ('chefchaouen', 'Talassemtane National Park', 'nature', 'Fir and cedar forests in the Rif mountains, with trails leaving from town.', 60),
  ('chefchaouen', 'Akchour Waterfalls', 'nature', 'A day hike to waterfalls and God''s Bridge, a natural rock arch, about 45 minutes'' drive away.', 70),
  ('ouarzazate', 'Aït Benhaddou', 'sight', 'A fortified earthen village and UNESCO site about 30 km away, seen in many films.', 10),
  ('ouarzazate', 'Taourirt Kasbah', 'sight', 'A 19th-century kasbah of the Glaoui family in the town centre.', 20),
  ('ouarzazate', 'Telouet Kasbah', 'sight', 'The crumbling, painted palace of the Glaoui family on the old Atlas caravan route, north of Ouarzazate.', 30),
  ('ouarzazate', 'Atlas Film Studios', 'sight', 'Film sets you can tour, just outside town.', 40),
  ('ouarzazate', 'Fint Oasis', 'nature', 'A hidden palm oasis a short drive from town.', 50),
  ('ouarzazate', 'Skoura Oasis', 'nature', 'Palm groves dotted with old kasbahs, east on the road to the Dades Valley.', 60),
  ('ouarzazate', 'Draa Valley', 'nature', 'A long river valley of palms and kasbahs running south towards Zagora.', 70),
  ('ifrane', 'Lion Stone', 'sight', 'The town’s famous stone lion, carved in the 1930s, in a park near the centre.', 10),
  ('ifrane', 'Ifrane town centre', 'square', 'Alpine-style houses with sloping roofs, flower gardens and cafés.', 20),
  ('ifrane', 'Ifrane National Park', 'nature', 'Cedar forests, lakes and Barbary macaques.', 30),
  ('ifrane', 'Azrou Cedar Forest', 'nature', 'Ancient Atlas cedars near the town of Azrou, where Barbary macaques live.', 40),
  ('ifrane', 'Dayet Aoua', 'nature', 'A lake circled by a walking trail, a short drive north of Ifrane.', 50),
  ('ifrane', 'Michlifen', 'nature', 'A ski area in a volcanic crater; snow depends on the winter.', 60),
  ('meknes', 'Bab Mansour', 'gate', 'One of the grandest gates in Morocco, covered in green and black zellige.', 10),
  ('meknes', 'Place el-Hedim', 'square', 'The big square in front of Bab Mansour, lively in the evening.', 20),
  ('meknes', 'Heri es-Souani', 'sight', 'Huge 17th-century granaries and stables built for Sultan Moulay Ismail.', 30),
  ('meknes', 'Volubilis', 'sight', 'Roman ruins and a UNESCO site about 30 km north. Go by grand taxi or on a half-day trip.', 40),
  ('merzouga', 'Erg Chebbi', 'nature', 'Orange sand dunes up to about 150 m high. Sunrise and sunset are the best times.', 10),
  ('merzouga', 'Desert camps', 'nature', 'Spend a night in a camp in the dunes, usually reached by camel or 4x4.', 20),
  ('merzouga', 'Khamlia', 'sight', 'A village known for its Gnawa music, a short drive south.', 30)
insert into public.parks (name, near, best_for, kind, sort_order) values
  ('Jardin Majorelle', 'Marrakech', 'Botanical garden', 'garden', 10),
  ('Menara Gardens', 'Marrakech', 'Gardens and Atlas viewpoints', 'garden', 20),
  ('Cyber Park', 'Marrakech', 'Shady green space in the city', 'park', 30),
  ('Perdicaris Park', 'Tangier', 'Forest walks and sea views', 'park', 40),
  ('Villa Harris Park', 'Tangier', 'Gardens and relaxing', 'garden', 50),
  ('Arab League Park', 'Casablanca', 'Central city park', 'park', 60),
  ('Bouskoura Forest', 'Casablanca', 'Walking and outdoor fun', 'park', 70),
  ('Jnan Sbil Gardens', 'Fes', 'Historic gardens', 'garden', 80),
  ('Jardin d''Essais Botaniques', 'Rabat', 'Botanical garden', 'garden', 90),
  ('Talassemtane National Park', 'Chefchaouen', 'Hiking and mountain scenery', 'national', 100),
  ('Ifrane National Park', 'Ifrane', 'Cedar forests and wildlife', 'national', 110),
  ('Souss-Massa National Park', 'Agadir region', 'Birdwatching and protected coast', 'national', 120),
  ('Toubkal National Park', 'High Atlas', 'Mountain trekking', 'national', 130),
  ('Al Hoceima National Park', 'Al Hoceima', 'Coastal nature', 'national', 140),
  ('Tazekka National Park', 'Taza', 'Forests and caves', 'national', 150)
insert into public.seasonal_recommendations (season, label, months, experiences, destinations, sort_order) values
  ('winter', 'Winter', 'December to February', 'Mild coastal weather, desert trips, and possible snow in the mountains.', array['Marrakech', 'Agadir', 'Merzouga', 'Ouarzazate', 'Ifrane']::text[], 10),
  ('spring', 'Spring', 'March to May', 'Gardens in bloom, sightseeing, hiking and waterfalls.', array['Marrakech', 'Chefchaouen', 'Fes', 'Rabat', 'Ourika Valley']::text[], 20),
  ('summer', 'Summer', 'June to August', 'Beaches, surfing, water sports and cool coastal escapes.', array['Agadir', 'Tangier', 'Essaouira', 'Al Hoceima', 'Dakhla']::text[], 30),
  ('autumn', 'Autumn', 'September to November', 'Desert excursions, historic cities and mountain trips.', array['Marrakech', 'Fes', 'Merzouga', 'Chefchaouen', 'Ouarzazate']::text[], 40)
